package com.indiesoundquest.async;
import java.time.*; import org.springframework.amqp.rabbit.core.RabbitTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.Transactional;
@Component public class OutboxPublisher { private final AsyncOutboxEventRepository events; private final RabbitTemplate rabbit; public OutboxPublisher(AsyncOutboxEventRepository events,RabbitTemplate rabbit){this.events=events;this.rabbit=rabbit;}
 @Scheduled(fixedDelayString="${async.outbox.publish-interval-ms:1000}") @Transactional public void publish(){for(var event:events.findTop20ByStatusAndNextAttemptAtLessThanEqualOrderByCreatedAtAsc("PENDING",Instant.now()))try{rabbit.convertAndSend(ReportQueueConfiguration.EXCHANGE,ReportQueueConfiguration.ROUTING_KEY,event.getPayloadJson(),m->{m.getMessageProperties().setHeader("traceId",event.getTraceId());return m;});event.published();}catch(Exception ignored){event.retry();}} }
